// Own source-receipt hashing only; never imports or executes reviewed/project code.
function createSourceHasher() {
function utf8(s){const a=[];for(let i=0;i<s.length;i++){let c=s.charCodeAt(i);if(c>=0xd800&&c<=0xdbff){const d=s.charCodeAt(++i);if(!(d>=0xdc00&&d<=0xdfff))throw Error("invalid surrogate");c=0x10000+((c-0xd800)<<10)+(d-0xdc00)}if(c<128)a.push(c);else if(c<2048)a.push(192|(c>>6),128|(c&63));else if(c<65536)a.push(224|(c>>12),128|((c>>6)&63),128|(c&63));else a.push(240|(c>>18),128|((c>>12)&63),128|((c>>6)&63),128|(c&63));}return a;}
function padded(bytes){let a=bytes.slice(),n=a.length*8;a.push(128);while(a.length%64!==56)a.push(0);for(let i=7;i>=0;i--)a.push(Math.floor(n/2**(8*i))&255);return a}
function words(a,k){return ((a[k]<<24)|(a[k+1]<<16)|(a[k+2]<<8)|a[k+3])>>>0}
function hex(a){return a.map(x=>(x>>>0).toString(16).padStart(8,"0")).join("")}
function sha1(bytes){const a=padded(bytes),h=[0x67452301,0xefcdab89,0x98badcfe,0x10325476,0xc3d2e1f0],r=(x,n)=>(x<<n)|(x>>>(32-n));for(let i=0;i<a.length;i+=64){const w=[];for(let j=0;j<16;j++)w[j]=words(a,i+4*j);for(let j=16;j<80;j++)w[j]=r(w[j-3]^w[j-8]^w[j-14]^w[j-16],1);let[A,B,C,D,E]=h;for(let j=0;j<80;j++){let f,k;if(j<20){f=(B&C)|(~B&D);k=0x5a827999}else if(j<40){f=B^C^D;k=0x6ed9eba1}else if(j<60){f=(B&C)|(B&D)|(C&D);k=0x8f1bbcdc}else{f=B^C^D;k=0xca62c1d6}const t=(r(A,5)+f+E+k+w[j])|0;E=D;D=C;C=r(B,30);B=A;A=t}for(let j=0;j<5;j++)h[j]=(h[j]+[A,B,C,D,E][j])|0;}return hex(h)}
function sha256(bytes){const a=padded(bytes),h=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19],k=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2],r=(x,n)=>(x>>>n)|(x<<(32-n));for(let i=0;i<a.length;i+=64){const w=[];for(let j=0;j<16;j++)w[j]=words(a,i+4*j);for(let j=16;j<64;j++){const x=w[j-15],y=w[j-2];w[j]=(w[j-16]+(r(x,7)^r(x,18)^(x>>>3))+w[j-7]+(r(y,17)^r(y,19)^(y>>>10)))|0}let[A,B,C,D,E,F,G,H]=h;for(let j=0;j<64;j++){const t1=(H+(r(E,6)^r(E,11)^r(E,25))+((E&F)^(~E&G))+k[j]+w[j])|0,t2=((r(A,2)^r(A,13)^r(A,22))+((A&B)^(A&C)^(B&C)))|0;H=G;G=F;F=E;E=(D+t1)|0;D=C;C=B;B=A;A=(t1+t2)|0;}for(let j=0;j<8;j++)h[j]=(h[j]+[A,B,C,D,E,F,G,H][j])|0;}return hex(h)}
return {utf8,sha1,sha256};
}
